  "scenario_id": "sc-2d248f",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "Yearly IP A/E ranges 0.413 to 1.654 with mean ~1.006; sample standard deviation of yearly A/E ≈0.38 vs Poisson/noise standard deviation ≈0.022-0.031 per year. Notable deviations: 2015 A/E 0.413 (~-19 sigma equivalent), 2016 1.654 (~+22 sigma), 2020 1.612 (~+24 sigma), 2022 0.740 (~-11 sigma), 2023 0.794 (~-9 sigma). Overall IP A/E remains 0.9995, so level is approximately unchanged but year-to-year dispersion is vastly excessive.",
      "confidence": 0.97,
      "evidence": [
        "artifacts/ae_ip_by_year.csv shows extreme IP A/E swings: 0.413 in 2015, 1.654 in 2016, 1.612 in 2020, 0.740 in 2022, 0.794 in 2023.",
        "summary.json reports overall IP A/E 0.9995 and overall termination A/E 1.0001, indicating the aggregate level is normal despite the yearly swings.",
        "artifacts/ae_ip_termination.csv shows diagnosis-level termination A/E mostly near 1.0 (0.951 to 1.036), giving no clear indication that this is a diagnosis-specific recovery-rate anomaly."
      ],
      "recommended_action": "Treat IP as a priority data-quality/reporting issue. Reconcile yearly IP actual claim counts to source systems, checking for missing/late claims, extract errors, restatements, policy-administration changes, exposure misalignment, or diagnosis-mix shifts in 2015-16, 2020, and 2022-23. If data are confirmed correct, review IP expected claim count/exposure model and consider volatility/claims experience monitoring; no immediate recovery-rate assumption change is indicated by the pooled termination A/E."
    }
  ]
}

